// wal — write-ahead log with replay and checkpoint
// Hash: sha256

fn wal_open::(path) {
    return {"path": path, "entries": [], "checkpoint": 0};
}

fn wal_append::(wal, op, key, value) {
    let entry = {"seq": @len(wal["entries"]), "ts": @time_ms(),
                  "op": op, "key": key, "value": value};
    @push(wal["entries"], entry);
    @append_text(wal["path"], @json_encode(entry) + "\n");
    return entry["seq"];
}

fn wal_replay::(wal) {
    if (!@exists(wal["path"])) { return 0; }
    let lines = @read_lines(wal["path"]);
    let entries = [];
    for line in lines {
        if (@str_is_blank(line)) { continue; }
        @push(entries, @json_decode(line));
    }
    wal["entries"] = entries;
    return @len(entries);
}

fn wal_apply::(wal, state) {
    let applied = 0;
    for e in wal["entries"] {
        if (e["seq"] <= wal["checkpoint"]) { continue; }
        if (e["op"] == "set") { state[e["key"]] = e["value"]; }
        else if (e["op"] == "del") { state = @map_omit_keys(state, [e["key"]]); }
        applied += 1;
    }
    return applied;
}

fn wal_checkpoint::(wal, seq) {
    wal["checkpoint"] = seq;
    let kept = [];
    for e in wal["entries"] { if (e["seq"] > seq) { @push(kept, e); } }
    wal["entries"] = kept;
    let out = "";
    for e in kept { out += @json_encode(e) + "\n"; }
    @write_text(wal["path"], out);
    return true;
}

fn wal_size::(wal) { return @len(wal["entries"]); }
fn version::() { return "1.0.0"; }
